SELECT 
  FROM public.agent_runtime_workflow_child_preparations
 WHERE tenant_id = #{tenantId}
   AND parent_execution_id = #{parentExecutionId}
   AND node_id = #{nodeId}
   AND visit = #{visit}
   AND call_index = #{callIndex}

SELECT 
  FROM public.agent_runtime_workflow_child_execution_sources
 WHERE tenant_id = #{tenantId}
   AND parent_execution_id = #{parentExecutionId}
   AND node_id = #{nodeId}
   AND visit = #{visit}
   AND call_index = #{callIndex}
 ORDER BY child_ordinal

SELECT 
  FROM public.agent_runtime_workflow_child_execution_sources
 WHERE tenant_id = #{tenantId}
   AND child_execution_id = #{childExecutionId}
